class Solution:
    def isRobotBounded(self, instructions: str) -> bool:
        dx = [0, 1, 0, -1]
        dy = [1, 0, -1, 0]
        x = y = 0
        di = 0
        for c in instructions:
            if c == 'G':
                x += dx[di]
                y += dy[di]
            elif c == 'L':
                di = (di - 1) % 4
            else:
                di = (di + 1) % 4
        return (x == 0 and y == 0) or di != 0

